/* anchor_frustum.h — wire the RDH-fed anchor (anchor_weight.h) INTO the
 * frustum descent (core/frustum_route.h) as its APEX.
 *
 * Owner spec (2026-10-10, memory #7536):
 *   "F.quadtree มันเกิดจาก anchor นี่แหละ" — the frustum quadtree is
 *   generated BY the anchor; the anchor IS the frustum apex. 6 directions
 *   (= the 6 faces), refining x4 per level: 1 < 4 < 16 < 64, and the
 *   level-16 slot is the new "major anchor" that chains onward.
 *
 * What already exists (do NOT rebuild):
 *   - core/anchor_route.h   : centroid router + MOD-37 placement
 *   - include/anchor_weight.h: RDH pattern -> per-anchor letters/weights
 *   - core/frustum_route.h  : fr_route_produce() does the 1<4<16<64 descent,
 *                             branch_path in [0,6), span narrows per level,
 *                             capo_key stable, replayable route_ref
 *   - core/frustum_trit.h   : TritAddr {trit,coset,face,level,letter,slope}
 *
 * What this file adds: the JOINT. An aw_anchor_t (RDH-derived) becomes the
 * apex of a frustum descent — its 6 centre letters select directions, its
 * slot weights bias the path, and the resulting 4-level event chain IS the
 * anchor's frustum.  The apex fingerprint (slope) folds the anchor + the
 * level-16 major-anchor identity so the chain can continue.
 *
 * Derive-don't-store: no tree is materialised. Address = f(anchor, level,
 * cell) computed in O(1) from the anchor bytes.
 *
 * Header-only, std-only.
 */
#ifndef ANCHOR_FRUSTUM_H
#define ANCHOR_FRUSTUM_H

#include <stdint.h>
#include <stddef.h>

#include "anchor_weight.h"      /* aw_anchor_t, RDH pattern */
#include "frustum_route.h"      /* fr_route_produce, FrustumSeeker, FR_MAX_DEPTH */
#include "frustum_trit.h"       /* TritAddr, FACE_COUNT, LEVEL_COUNT */

/* level -> cells at that level: 1, 4, 16, 64 (x4 per layer). Owner's
 * "1<4<16<64". Index by level 0..3. */
static const uint32_t AF_LEVEL_CELLS[LEVEL_COUNT] = { 1u, 4u, 16u, 64u };

/* apex fingerprint: the anchor's slot weights + letters folded into a
 * slope seed. This is the anchor_tess/frustum_trit slope idea applied to
 * the RDH-derived anchor: deterministic, no state. */
static inline uint64_t af_apex_slope(const aw_anchor_t *a) {
    uint64_t h = 1469598103934665603ull;   /* FNV-1a 64 offset */
    h ^= a->letter;              h *= 1099511628211ull;
    for (int s = 0; s < (int)AW_OUTER; s++) {
        h ^= a->weight[s];       h *= 1099511628211ull;
        h ^= a->fold16[s];       h *= 1099511628211ull;
    }
    return h;
}

/* anchor -> the 6 direction letters (already distinct, spec #7539) mapped
 * onto the frustum FACE_COUNT=6. dir_letter[d] is the face-d letter. */
static inline uint8_t af_face_letter(const aw_anchor_t *a, int face) {
    if (face < 0 || face >= (int)FACE_COUNT) return 0;
    return a->dir_letter[face];
}

/* anchor -> apex position in the 20736 field: the anchor's letters/weights
 * decide WHERE the frustum apex sits. Deterministic from the anchor only. */
static inline uint32_t af_apex_pos(const aw_anchor_t *a) {
    uint32_t p = (uint32_t)a->letter;
    for (int s = 0; s < (int)AW_OUTER; s++)
        p = p * 31u + a->weight[s] + a->fold4[s];
    return p % 20736u;
}

/* The joint itself: given an anchor, produce its frustum descent — one
 * FrustumRouteEvent per level (coarse -> fine), branch_path taken from the
 * anchor's direction at that level, capo carried through. Returns the
 * number of levels produced (FR_MAX_DEPTH) or 0 on failure.
 *
 * The descent uses the EXISTING fr_route_produce() — no descent logic is
 * duplicated here; this only seeds it from the RDH anchor. */
static inline int af_anchor_descent(const aw_anchor_t *a,
                                    FrustumRouteEvent out[FR_MAX_DEPTH]) {
    if (!a || !out) return 0;
    FrRouteCache cache;
    fr_cache_init(&cache);
    uint32_t pos = af_apex_pos(a);
    uint64_t slope = af_apex_slope(a);
    int produced = 0;
    for (int d = (int)FR_MAX_DEPTH - 1; d >= 0; d--) {
        FrustumSeeker s;
        s.position = pos;                      /* fixed apex slot, read digit d */
        s.view_id  = (uint8_t)(slope & 0x7u);  /* apex fingerprint picks the view */
        s.voronoi_mask = 0xFFFFFFu;            /* geometry only */
        s.frustum_depth = (uint8_t)(d + 1);    /* depth d+1 -> level d */
        FrustumRouteEvent ev;
        if (!fr_route_produce(&s, &cache, &ev)) return 0;
        /* bias the branch toward the anchor's heavier slots (fixed weight,
         * memory #7537): the anchor's weight steers which face is walked. */
        int bias = aw_weight_bias(a, d);       /* -8..+8 */
        if (bias > 0) ev.branch_path = (uint8_t)((ev.branch_path + (uint32_t)bias) % FACE_COUNT);
        out[produced++] = ev;
    }
    return produced;
}

/* level-16 major anchor (owner: "face=4vertex>16 new major anchor").
 * The level-2 event (16 cells) becomes the identity of the next anchor in
 * the chain, so the chain can continue into a child anchor. Deterministic
 * fold of the event's stable fields into a 32-bit child seed. */
static inline uint32_t af_major_anchor_seed(const FrustumRouteEvent *lvl16) {
    if (!lvl16) return 0;
    uint64_t h = 1469598103934665603ull;
    h ^= lvl16->branch_path;  h *= 1099511628211ull;
    h ^= lvl16->capo_key;     h *= 1099511628211ull;
    h ^= lvl16->span_size;    h *= 1099511628211ull;
    h ^= (lvl16->route_ref & 0xFFFFFFFFu);
    return (uint32_t)(h ^ (h >> 32));
}

/* chain one step: current anchor -> child anchor seed (derived from the
 * level-2 / 16-cell event). The child's bytes are the seed expanded
 * deterministically, so the whole sub-anchor is derived, not stored. */
static inline void af_child_seed_bytes(uint32_t child_seed, uint8_t *out, size_t n) {
    uint32_t s = child_seed ? child_seed : 1u;
    for (size_t i = 0; i < n; i++) {
        s ^= s << 13; s ^= s >> 17; s ^= s << 5;
        out[i] = (uint8_t)s;
    }
}

/* anchor -> TritAddr (frustum_trit.h): the trit-address form of the anchor,
 * so the anchor joins the existing trit/slot64 store path. coset/face/level
 * derive from the anchor's letters; slope = apex fingerprint. */
static inline TritAddr af_anchor_trit(const aw_anchor_t *a) {
    TritAddr t;
    uint8_t trit = (uint8_t)(a->letter % TRIT_MOD);
    trit_decompose(trit, &t);
    t.letter = (uint8_t)(a->letter % LETTER_COUNT);  /* 0..25 A..Z */
    t.slope  = af_apex_slope(a);
    return t;
}

#endif /* ANCHOR_FRUSTUM_H */
